/** `@generated`: the database computes the column; the engine refuses a write that names it, before SQL. */
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { connect, loads, Registry } from "../src/index.js";
import { native } from "../src/native.js";

const source = `
model Line {
  id       Int @id
  quantity Int
  price    Int
  total    Int @generated(quantity * price)
  @@map("generated_node_lines")
}
`;
type Line = { id: number; quantity: number; price: number; total: number };

for (const dialect of ["sqlite", "postgres"]) {
  test(`insert returns the generated value and every write refuses it (${dialect})`, async () => {
    const registry = new Registry();
    const Line = loads((dialect === "sqlite" ? 'datasource db { provider = "sqlite" }\n' : "") + source, { registry }).Line!;
    const url = dialect === "sqlite" ? "sqlite://:memory:" : process.env.ORM_TEST_DATABASE_URL ?? "postgres://postgres:postgres@localhost/orm_test";
    const db = await connect(url, { registry, default: false });
    await db.createTables();
    const lines = Line.objects.using(db);
    const columns = Line as unknown as Record<string, never>;
    try {
      assert.equal(((await lines.insert({ id: 1, quantity: 3, price: 4 })) as Line).total, 12);
      const many = (await lines.insertMany([{ id: 2, quantity: 5, price: 6 }, { id: 3, quantity: 1, price: 1 }]).returning()) as Line[];
      assert.deepEqual(many.map((r) => r.total), [30, 1]);
      await lines.filter((columns.id as unknown as { eq(v: number): never }).eq(1)).update({ quantity: 10 });
      assert.equal(((await lines.filter((columns.id as unknown as { eq(v: number): never }).eq(1)).get()) as Line).total, 40);
      const wanted = { message: /Line\.total is generated by the database/ };
      const bad: Record<string, number> = { total: 1 };
      await assert.rejects(async () => lines.insert({ id: 9, quantity: 1, price: 1, ...bad } as never), wanted);
      await assert.rejects(async () => lines.insertMany([{ id: 9, quantity: 1, price: 1, ...bad } as never]), wanted);
      await assert.rejects(async () => lines.all().update(bad as never), wanted);
      await assert.rejects(async () => lines.updateMany([{ id: 1, ...bad } as never]), wanted);
      await assert.rejects(async () => lines.insert({ id: 1, quantity: 1, price: 1 }).onConflict(columns.id!, { update: true, updateFields: [columns.total!] as never }), wanted);
      await assert.rejects(async () => lines.insert({ id: 1, quantity: 1, price: 1 }).onConflict(columns.id!, { update: true, updateValues: bad as never }), wanted);
      assert.equal(((await lines.filter((columns.id as unknown as { eq(v: number): never }).eq(1)).get()) as Line).total, 40);
    } finally { await db.dropTables(); await db.close(); }
  });
}

for (const dialect of ["sqlite", "postgres"]) {
  test(`a unique generated field is a conflict target (${dialect})`, async () => {
    const registry = new Registry();
    const unique = source.replace("total    Int @generated", "total    Int @unique @generated");
    const Line = loads((dialect === "sqlite" ? 'datasource db { provider = "sqlite" }\n' : "") + unique, { registry }).Line!;
    const url = dialect === "sqlite" ? "sqlite://:memory:" : process.env.ORM_TEST_DATABASE_URL ?? "postgres://postgres:postgres@localhost/orm_test";
    const db = await connect(url, { registry, default: false });
    await db.createTables();
    const lines = Line.objects.using(db);
    const columns = Line as unknown as Record<string, never>;
    try {
      await lines.insert({ id: 1, quantity: 3, price: 4 });
      // The same total (12) conflicts on the generated column, and the row is skipped.
      await lines.insert({ id: 2, quantity: 2, price: 6 }).onConflict(columns.total!, { update: false });
      assert.deepEqual(((await lines.all()) as Line[]).map((r) => r.id), [1]);
    } finally { await db.dropTables(); await db.close(); }
  });
}

test("a virtual generated column reads on sqlite", async () => {
  const registry = new Registry();
  const Line = loads('datasource db { provider = "sqlite" }\n' + source.replace("(quantity * price)", "(quantity * price, stored: false)"), { registry }).Line!;
  const db = await connect("sqlite://:memory:", { registry, default: false });
  await db.createTables();
  try { assert.equal(((await Line.objects.using(db).insert({ id: 1, quantity: 2, price: 7 })) as Line).total, 14); } finally { await db.close(); }
});

test("a virtual generated column reads on postgres", async (t) => {
  const registry = new Registry();
  const Line = loads(source.replace("(quantity * price)", "(quantity * price, stored: false)"), { registry }).Line!;
  const db = await connect(process.env.ORM_TEST_DATABASE_URL ?? "postgres://postgres:postgres@localhost/orm_test", { registry, default: false });
  try {
    if (Number((await db.fetchText("SHOW server_version_num"))[0]![0]) < 180000) return t.skip("VIRTUAL generated columns need PostgreSQL 18");
    await db.createTables();
    assert.equal(((await Line.objects.using(db).insert({ id: 1, quantity: 2, price: 7 })) as Line).total, 14);
    await assert.rejects(async () => Line.objects.using(db).all().update({ total: 1 } as never), { message: /Line\.total is generated by the database/ });
  } finally { await db.dropTables(); await db.close(); }
});

test("the insert and update types leave out the generated field", (t) => {
  const dir = mkdtempSync(join(tmpdir(), "monorm-generated-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const schema = join(dir, "schema.prisma");
  writeFileSync(schema, source);
  const text = native().generateTypescript(schema);
  for (const shape of ["LineInsert", "LineUpdate", "LineUpdateRow"]) {
    const block = new RegExp(`export (?:type|interface) ${shape}\\b[^]*?\\n}`).exec(text)?.[0];
    assert.ok(block, shape);
    assert.ok(block.includes("quantity") && !block.includes("total"), shape);
  }
  assert.ok(/export interface LineData \{[^]*?total/.test(text));
});
